mapper.select:

SELECT
    COUNT(*)                                                         AS total_count,
    IFNULL(SUM(CASE WHEN body_quality = 'GOOD' THEN 1 ELSE 0 END), 0) AS good_count,
    IFNULL(SUM(CASE WHEN body_quality = 'NG'   THEN 1 ELSE 0 END), 0) AS bad_count
FROM vision_inspection_log
WHERE line_no = #{lineNo}
  AND timestamp >= #{from}
  AND timestamp < #{to}

SELECT
    run_time_sec, idle_time_sec, stop_time_sec, alarm_time_sec,
    total_count, good_count, bad_count,
    availability, performance, quality, oee
FROM line_summary
WHERE line_no = #{lineNo}
  AND summary_start_time = #{from}
  AND summary_end_time   = #{to}
LIMIT 1

mapper.delete:
DELETE FROM line_summary
WHERE line_no = #{lineNo}
  AND summary_start_time = #{from}
  AND summary_end_time   = #{to}

mapper.select:

SELECT COUNT(*)
FROM equipment_status_log
WHERE equipment_id = #{equipmentId}
  AND status = 'ALARM'
  AND start_time < #{to}
  AND IFNULL(end_time, #{to}) > #{from}

SELECT
    run_time_sec, idle_time_sec, stop_time_sec, alarm_time_sec,
    availability, performance, quality, oee,
    mttf_sec, mtbf_sec, mttr_sec,
    health_score, remaining_life, replacement_date
FROM equipment_summary
WHERE equipment_id = #{equipmentId}
  AND summary_start_time = #{from}
  AND summary_end_time   = #{to}
LIMIT 1

mapper.delete:
DELETE FROM equipment_summary
WHERE equipment_id = #{equipmentId}
  AND summary_start_time = #{from}
  AND summary_end_time   = #{to}

mapper.update:
UPDATE equipment
SET health_score          = #{healthScore},
    accumulated_run_hours = #{accumulatedRunHours},
    remaining_life        = #{remainingLife},
    replacement_date      = #{replacementDate}
WHERE equipment_id = #{equipmentId}
